Contract CoCoMEOrderProducts::orderItem(barcode:Integer,quantity:Integer): Boolean {
          definition:
          item:Item = Item.allInstance()->any(o | o.Barcode = barcode), orderEntry:OrderEntry = OrderEntry{}

            precondition:
          item.oclIsUndefined() = bool

            postcondition:
          let orderEntry:OrderEntry in orderEntry.oclIsNew() and orderEntry.Quantity = quantity and orderEntry.SubAmount = item.Price * quantity and orderEntry.Item = item and CurrentOrderProduct.ContainedEntries->includes(orderEntry) and result = true

        }
